$ErrorActionPreference = 'Stop'
Set-StrictMode -Version Latest

$root = (Get-Location).Path
if (-not (Test-Path (Join-Path $root 'pubspec.yaml'))) {
    throw 'Run this script from the almustafa-connect-erp project root.'
}

$utf8 = New-Object System.Text.UTF8Encoding($false)
$stamp = Get-Date -Format 'yyyyMMdd_HHmmss'
$backupRoot = Join-Path (Split-Path $root -Parent) "almustafa-connect-erp_backups/academic_calendar_phase1_$stamp"

function Read-ProjectFile {
    param([Parameter(Mandatory = $true)][string]$RelativePath)
    $path = Join-Path $root $RelativePath
    if (-not (Test-Path $path)) { throw "Required file not found: $RelativePath" }
    return [IO.File]::ReadAllText($path).Replace("`r`n", "`n")
}

function Write-ProjectFile {
    param(
        [Parameter(Mandatory = $true)][string]$RelativePath,
        [Parameter(Mandatory = $true)][string]$Content
    )
    $path = Join-Path $root $RelativePath
    New-Item -ItemType Directory -Path (Split-Path $path -Parent) -Force | Out-Null
    [IO.File]::WriteAllText($path, $Content, $utf8)
    Write-Host "Created/updated: $RelativePath" -ForegroundColor Green
}

function Backup-ProjectFile {
    param([Parameter(Mandatory = $true)][string]$RelativePath)
    $source = Join-Path $root $RelativePath
    if (-not (Test-Path $source)) { return }
    $destination = Join-Path $backupRoot $RelativePath
    New-Item -ItemType Directory -Path (Split-Path $destination -Parent) -Force | Out-Null
    Copy-Item $source $destination -Force
}

function Ensure-BeforeAnchor {
    param(
        [Parameter(Mandatory = $true)][string]$Content,
        [Parameter(Mandatory = $true)][string]$UniqueMarker,
        [Parameter(Mandatory = $true)][string]$Anchor,
        [Parameter(Mandatory = $true)][string]$Block
    )
    if ($Content.Contains($UniqueMarker)) { return $Content }
    $index = $Content.IndexOf($Anchor)
    if ($index -lt 0) { throw "Integration anchor not found: $Anchor" }
    return $Content.Substring(0, $index) + $Block + $Content.Substring($index)
}

$payloads = @{
    'lib/features/academic_calendar/domain/entities/academic_calendar_event_entity.dart' = ''
    'lib/features/academic_calendar/data/models/academic_calendar_event_model.dart' = ''
    'lib/features/academic_calendar/domain/repositories/academic_calendar_repository.dart' = ''
    'lib/features/academic_calendar/data/repositories/academic_calendar_repository_impl.dart' = ''
    'lib/features/academic_calendar/presentation/bloc/academic_calendar_bloc.dart' = ''
    'lib/features/academic_calendar/presentation/pages/academic_calendar_page.dart' = ''
}
$firestorePaths = 'lib/core/constants/firestore_paths.dart'
$serviceLocator = 'lib/core/di/service_locator.dart'
$sidebar = 'lib/features/dashboard/presentation/widgets/sidebar.dart'

foreach ($relativePath in (@($firestorePaths, $serviceLocator, $sidebar) + $payloads.Keys)) {
    Backup-ProjectFile -RelativePath $relativePath
}

foreach ($item in $payloads.GetEnumerator()) {
    $text = [Text.Encoding]::UTF8.GetString(
        [Convert]::FromBase64String($item.Value)
    )
    Write-ProjectFile -RelativePath $item.Key -Content $text
}

# Firestore path
$content = Read-ProjectFile -RelativePath $firestorePaths
if (-not $content.Contains('academicCalendarEvents')) {
    $content = $content.Replace(
        "`n}",
        "`n  static const String academicCalendarEvents = 'academic_calendar_events';`n}"
    )
}
Write-ProjectFile -RelativePath $firestorePaths -Content $content

# Service locator
$content = Read-ProjectFile -RelativePath $serviceLocator

$content = Ensure-BeforeAnchor `
    -Content $content `
    -UniqueMarker 'academic_calendar_repository_impl.dart' `
    -Anchor "import '../../features/academic_structure/data/repositories/academic_structure_repository_impl.dart';" `
    -Block "import '../../features/academic_calendar/data/repositories/academic_calendar_repository_impl.dart';`n"

$content = Ensure-BeforeAnchor `
    -Content $content `
    -UniqueMarker 'academic_calendar_repository.dart' `
    -Anchor "import '../../features/academic_structure/domain/repositories/academic_structure_repository.dart';" `
    -Block "import '../../features/academic_calendar/domain/repositories/academic_calendar_repository.dart';`n"

$content = Ensure-BeforeAnchor `
    -Content $content `
    -UniqueMarker 'academic_calendar_bloc.dart' `
    -Anchor "import '../../features/academic_structure/presentation/bloc/academic_structure_bloc.dart';" `
    -Block "import '../../features/academic_calendar/presentation/bloc/academic_calendar_bloc.dart';`n"

$repoRegistration = @'
  sl.registerLazySingleton<AcademicCalendarRepository>(
    () => AcademicCalendarRepositoryImpl(
      sl<FirebaseFirestoreService>(),
    ),
  );

'@

$content = Ensure-BeforeAnchor `
    -Content $content `
    -UniqueMarker 'registerLazySingleton<AcademicCalendarRepository>' `
    -Anchor '  sl.registerLazySingleton<AcademicStructureRepository>(' `
    -Block $repoRegistration

$blocRegistration = @'
  sl.registerFactory<AcademicCalendarBloc>(
    () => AcademicCalendarBloc(
      sl<AcademicCalendarRepository>(),
    ),
  );

'@

$content = Ensure-BeforeAnchor `
    -Content $content `
    -UniqueMarker 'registerFactory<AcademicCalendarBloc>' `
    -Anchor '  sl.registerFactory<AcademicStructureBloc>(' `
    -Block $blocRegistration

Write-ProjectFile -RelativePath $serviceLocator -Content $content

# Sidebar: replace placeholder navigation for Academic Calendar.
$content = Read-ProjectFile -RelativePath $sidebar

$content = Ensure-BeforeAnchor `
    -Content $content `
    -UniqueMarker "academic_calendar/presentation/pages/academic_calendar_page.dart" `
    -Anchor "import '../../../attendance/presentation/pages/attendance_page.dart';" `
    -Block "import '../../../academic_calendar/presentation/pages/academic_calendar_page.dart';`n"

$placeholderPattern = "(?s)_menuTile\(\s*context,\s*icon:\s*Icons\.calendar_today_outlined,\s*title:\s*'Academic Calendar',\s*onTap:\s*\(\)\s*\{.*?ModulePlaceholderPage\(.*?title:\s*'Academic Calendar'.*?\}\s*,\s*\),"

$replacement = @'
_menuTile(
            context,
            icon: Icons.calendar_today_outlined,
            title: 'Academic Calendar',
            onTap: () {
              Navigator.of(context).push(
                MaterialPageRoute<void>(
                  builder: (_) => const AcademicCalendarPage(),
                ),
              );
            },
          ),
'@

if ([regex]::IsMatch($content, $placeholderPattern)) {
    $content = [regex]::Replace(
        $content,
        $placeholderPattern,
        $replacement,
        1
    )
} elseif (-not $content.Contains('const AcademicCalendarPage()')) {
    throw 'Could not locate Academic Calendar sidebar item.'
}

Write-ProjectFile -RelativePath $sidebar -Content $content

$formatFiles = @($firestorePaths, $serviceLocator, $sidebar) + $payloads.Keys

Write-Host ''
Write-Host 'Running dart format...' -ForegroundColor Cyan
& dart format $formatFiles
if ($LASTEXITCODE -ne 0) { throw 'dart format failed.' }

Write-Host ''
Write-Host 'Running flutter analyze...' -ForegroundColor Cyan
& flutter analyze
if ($LASTEXITCODE -ne 0) {
    throw 'flutter analyze found issues. Copy the complete output into ChatGPT.'
}

Write-Host ''
Write-Host 'Academic Calendar Phase 1 completed successfully.' -ForegroundColor Green
Write-Host "Backup: $backupRoot" -ForegroundColor DarkGray
